-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;

-- The DateTime64(9) branch carries no explicit timezone, so it is rendered in the session timezone,
-- which the stateless test harness randomizes. Pin it to UTC so the output is deterministic (the
-- DateTime64(9, 'UTC') branch is always rendered in UTC regardless of the session timezone).
SET session_timezone = 'UTC';

-- ORC uniontype<timestamp, timestamp with local timezone>. The two kinds are inferred as
-- DateTime64(9) and DateTime64(9, 'UTC') respectively, but both read back physically as
-- DateTime64(9). The union-branch matcher must keep them apart (TIMESTAMP_INSTANT is matched only
-- by a UTC-timezoned target) so that this valid file is not rejected by the duplicate-branch check.
-- Rows: local 1s, UTC NULL, local NULL, UTC 4s, local 2s (a null payload in each branch becomes a
-- Variant NULL, including on the UTC branch that receives the DateTime64 -> DateTime64('UTC') cast).
SELECT toTypeName(u) FROM format(ORC, unhex('')) LIMIT 1;
SELECT u FROM format(ORC, unhex('')) ORDER BY toString(u);

-- The same file with an explicit schema. DateTime64(9) and DateTime64(9, 'UTC') are considered
-- similar variant types, so allow_suspicious_variant_types is required to name them explicitly.
SET allow_suspicious_variant_types = 1;
SELECT u FROM format(ORC, $$u Variant(DateTime64(9), DateTime64(9, 'UTC'))$$, unhex('')) ORDER BY toString(u);

-- The branches of an explicit Variant are matched structurally, not positionally, so the reversed
-- order reads identically.
SELECT u FROM format(ORC, $$u Variant(DateTime64(9, 'UTC'), DateTime64(9))$$, unhex('')) ORDER BY toString(u);

-- Regression: an explicit schema whose instant branch carries a NON-UTC timezone. The
-- TIMESTAMP_INSTANT matcher accepts any explicit timezone (not only UTC), so the instant branch
-- is uniquely assigned DateTime64(9, 'Europe/Berlin') by singles-elimination and the file is not
-- rejected. The instant branch is relabelled to Europe/Berlin by the repair cast (its 4s value
-- renders one hour ahead of UTC), while the plain DateTime64(9) branch renders in the session
-- timezone (UTC, pinned above).
SELECT u FROM format(ORC, $$u Variant(DateTime64(9), DateTime64(9, 'Europe/Berlin'))$$, unhex('')) ORDER BY toString(u);
